/**
 * Rooms, Beta (ARCHITECTURE §3.7).
 */
import type {
  EpochMs,
  PackId,
  QuizId,
  RoomCode,
  RoomId,
  SeatId,
} from "./ids.ts";

export type RoomPhase =
  | "lobby"
  | "read"
  | "answering"
  | "reveal"
  | "standings"
  | "paused"
  | "podium"
  | "ended";
export interface RoomSettings {
  /** null: host advances. */
  timerSeconds: 10 | 20 | 30 | 60 | null;
  scoring: "classic" | "accuracy";
  /** typed: phones may set a filtered name (§8.11); generated by default. */
  names: "generated" | "typed";
}
export type RoomSource =
  { kind: "pack"; packId: PackId } | { kind: "quiz"; quizId: QuizId };

/** The only thing Realtime carries. A hint to refetch, never truth. */
export interface RoomHint {
  roomId: RoomId;
  version: number;
  phase: RoomPhase;
  questionIndex: number;
  deadline: EpochMs | null;
}

export interface RoomQuestionView {
  index: number;
  total: number;
  isFinal: boolean;
  stem: string;
  /** null until the server clock passes optionsAt: the read beat never carries them. */
  options: string[] | null;
  optionsAt: EpochMs;
  deadline: EpochMs | null;
}
export interface RoomRevealView {
  correctIndex: number;
  distribution: number[];
  explanation: string;
  voided: boolean;
}
export interface RoomStanding {
  seatId: SeatId;
  name: string;
  score: number;
  rank: number;
}

export interface RoomPlayerView {
  roomId: RoomId;
  version: number;
  phase: RoomPhase;
  locked: boolean;
  serverTime: EpochMs;
  /** No host call for 60 s; the room ends after 15 minutes away. */
  hostAway: boolean;
  names: "generated" | "typed";
  me: {
    seatId: SeatId;
    name: string;
    score: number;
    rank: number | null;
    gapAbove: number | null;
    aboveName: string | null;
    answered: boolean;
    last: { correct: boolean; points: number } | null;
    extraTime: boolean;
    /** A seat that joined mid-question scores from the next one. */
    scoresFrom: number;
  };
  question: RoomQuestionView | null;
  reveal: RoomRevealView | null;
  podium: RoomStanding[] | null;
  notice: "final_question" | "voided" | "removed" | "ended" | null;
}

export interface RoomSeatView {
  seatId: SeatId;
  name: string;
  connected: boolean;
  score: number;
  answered: boolean;
  extraTime: boolean;
  removed: boolean;
}
export interface RoomHostView {
  roomId: RoomId;
  code: RoomCode;
  version: number;
  phase: RoomPhase;
  locked: boolean;
  settings: RoomSettings;
  serverTime: EpochMs;
  questionCount: number;
  /** false while locked, full or at the project's connection cap. */
  joinsOpen: boolean;
  seats: RoomSeatView[];
  answeredCount: number;
  connectedCount: number;
  question: RoomQuestionView | null;
  reveal: RoomRevealView | null;
  top: RoomStanding[] | null;
  podium: RoomStanding[] | null;
}

export type RoomHostAction =
  | { kind: "start" }
  | { kind: "skip_read" }
  | { kind: "extend_all" }
  | { kind: "extra_time"; seatId: SeatId; on: boolean }
  | { kind: "reveal" }
  | { kind: "next" }
  | { kind: "pause" }
  | { kind: "resume" }
  | { kind: "remove"; seatId: SeatId }
  | { kind: "rename"; seatId: SeatId; name: string }
  | { kind: "lock"; locked: boolean }
  | { kind: "end" };
